import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { LoginParams, PinNumRequestDTO } from '~/entities/pin/api/dtos/types';
import { getLatestTranskeyModel } from '~/entities/pin/lib/get-latest-transkey-model';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { LoginType } from '~/shared/api/dtos/enums';
import { resultify } from '~/shared/lib/utils/resultify';

const verifyPin = (pinModel: PinNumRequestDTO) => {
  if (!pinModel.tbCstmrMastr?.cstmrNo) {
    throw new Error('cstmrNo is required');
  }

  const transkeyModel = getLatestTranskeyModel(pinModel.transkeyModel);
  const paramSid: string = pinModel.sid || '';

  const loginForm = new FormData();
  loginForm.append('pin', '');
  loginForm.append('sid', paramSid);
  loginForm.append('transkeyModel', transkeyModel ? JSON.stringify(transkeyModel) : '');
  const instance = axios.create({
    headers: {
      'Content-Type': 'multipart/form-data',
      loginTy: LoginType.간편비밀번호,
    },
  });

  return resultify<LoginParams>(instance.postForm(`${API_URLS.verifyPin}`, loginForm));
};

export const useVerifyPinMutation = (options?: MutationOptions<PinNumRequestDTO, CBDCAxiosError, LoginParams>) => {
  const setIncorrectPinCount = useStore.getState().pinSlice.setIncorrectPinCount;
  const mutation = useMutation<LoginParams, CBDCAxiosError, PinNumRequestDTO>({
    mutationFn: (pinModel: PinNumRequestDTO) => verifyPin(pinModel),
    onSuccess: (data) => {
      setIncorrectPinCount(0);

      const { setJwt } = useStore.getState().authSlice;
      setJwt(data.accessToken);
    },
    ...options,
  });

  return {
    ...mutation,
  };
};
